    let Some(view) = ctx.ssm_batch else {
        return Ok(false);
    };
    ensure!(
        (2..=8).contains(&rows)
            && rows <= ctx.levers.max_decode_seqs as usize
            && view.layer(0)?.rows() as usize == rows
